def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width row clues are the bands of a horizontal repeating pattern.
    bars = {r: row[0] for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)}
    if bars:
        period = len(bars)
        motif = {r % period: color for r, color in bars.items()}
        if len(motif) == period:
            return [[motif[r % period] for _ in range(w)] for r in range(h)]

    cells = [(r, c, value) for r, row in enumerate(grid)
             for c, value in enumerate(row) if value]
    if not cells:
        return [row[:] for row in grid]

    # The colored diagonal tracks form one complete period; their number gives
    # the period, and their invariant coordinate gives each track's phase.
    candidates = []
    for key_fn in (lambda r, c: c-r, lambda r, c: r+c):
        tracks = {}
        for r, c, color in cells:
            tracks.setdefault(key_fn(r, c), []).append(color)
        candidates.append((sum(len(v) ** 2 for v in tracks.values()), key_fn, tracks))
    _, key_fn, tracks = max(candidates, key=lambda item: item[0])

    track_colors = {}
    for key, values in tracks.items():
        track_colors[key] = max(set(values), key=values.count)
    period = len(track_colors)
    motif = {key % period: color for key, color in track_colors.items()}
    if len(motif) != period:
        return [row[:] for row in grid]
    return [[motif[key_fn(r, c) % period] for c in range(w)] for r in range(h)]

